package csu.mengya.controller;
import csu.mengya.db.AppDatabase;import javafx.collections.*;import javafx.fxml.*;import javafx.scene.control.*;import javafx.scene.layout.*;import java.net.URL;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.ResourceBundle;
public class ScheduleController implements Initializable { @FXML DatePicker datePicker;@FXML ComboBox<String> timeBox,typeBox;@FXML TextField eventField;@FXML GridPane weekGrid;@FXML Label scheduleStatus;final ObservableList<Event> events=FXCollections.observableArrayList();Event selected;public void initialize(URL u,ResourceBundle r){datePicker.setValue(LocalDate.now());timeBox.setItems(FXCollections.observableArrayList("08:00","09:00","10:00","11:00","14:00","15:00","16:00","19:00","20:00"));timeBox.setValue("09:00");typeBox.setItems(FXCollections.observableArrayList("学习","待办","专注"));typeBox.setValue("学习");datePicker.valueProperty().addListener((o,a,b)->render());load();}void load(){events.clear();for(AppDatabase.EventRow e:AppDatabase.events())events.add(new Event(e.id(),LocalDate.parse(e.date()),e.time(),e.name(),e.type()));render();}@FXML void addEvent(){String n=eventField.getText().trim();if(n.isEmpty()){scheduleStatus.setText("请输入日程名称");return;}AppDatabase.addEvent(datePicker.getValue().toString(),timeBox.getValue(),n,typeBox.getValue());eventField.clear();load();scheduleStatus.setText("日程已添加");}@FXML void deleteSelected(){if(selected!=null){AppDatabase.deleteEvent(selected.id);selected=null;load();scheduleStatus.setText("日程已删除");}}void render(){weekGrid.getChildren().clear();LocalDate base=datePicker.getValue().with(DayOfWeek.MONDAY);for(int i=0;i<7;i++){LocalDate d=base.plusDays(i);Label h=new Label(d.format(DateTimeFormatter.ofPattern("E MM/dd")));h.getStyleClass().add("calendar-header");weekGrid.add(h,i,0);VBox cell=new VBox(6);for(Event e:events)if(e.date.equals(d)){Button b=new Button(e.time+"  "+e.name);b.setMaxWidth(Double.MAX_VALUE);b.setOnAction(x->{selected=e;scheduleStatus.setText("已选择："+e.name);});b.getStyleClass().add("event-button");cell.getChildren().add(b);}weekGrid.add(cell,i,1);GridPane.setHgrow(cell,Priority.ALWAYS);}}static class Event{final long id;final LocalDate date;final String time,name,type;Event(long i,LocalDate d,String t,String n,String y){id=i;date=d;time=t;name=n;type=y;}}}